196 |         uint32 blockTimestamp = uint32(block.timestamp);
197 |         uint32 timeElapsed = blockTimestamp - blockTimestampLast; // overflow is desired
198 |         if (timeElapsed > 0 && _baseCached != 0 && _fyTokenCached != 0) {
199 |             // We multiply by 1e27 here so that r = t * y/x is a fixed point factor with 27 decimals 
200 |             uint256 scaledFYTokenCached = uint256(_fyTokenCached) * 1e27;
201 |             cumulativeBalancesRatio += scaledFYTokenCached  * timeElapsed / _baseCached;
202 |         }
203 |         baseCached = baseBalance.u112();
204 |         fyTokenCached = fyBalance.u112();
205 |         blockTimestampLast = blockTimestamp;
206 |         emit Sync(baseCached, fyTokenCached, cumulativeBalancesRatio);
207 |     }
